export function wrapNamedExpressionLhs(
	data: T.NamedExpressionLhs & { readonly $other?: T.NamedExpressionLhs | readonly T.NamedExpressionLhs[] },
	tree: TreeHandle
): SupertypeSurface<T.NamedExpressionLhs, T.ParsedByKindId> {
	if (typeof data === 'number') return data as unknown as SupertypeSurface<T.NamedExpressionLhs, T.ParsedByKindId>;
	const node = _keepModelledSlots(data, [
		'_identifier',
		'_print_keyword',
		'_exec_keyword',
		'_async_keyword',
		'_await_keyword',
		'_type_keyword',
		'_match_keyword'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'identifier',
		'print_keyword',
		'exec_keyword',
		'async_keyword',
		'await_keyword',
		'type_keyword',
		'match_keyword'
	]) as T.NamedExpressionLhs | readonly T.NamedExpressionLhs[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'identifier',
			'print_keyword',
			'exec_keyword',
			'async_keyword',
			'await_keyword',
			'type_keyword',
			'match_keyword'
		]);
	if (filtered === undefined && (typeof (node as _NodeData).$text === 'string' || treeHandleOf(node) !== undefined)) {
		return drillInSelf<T.NamedExpressionLhs>(node as T.NamedExpressionLhs, tree) as unknown as SupertypeSurface<
			T.NamedExpressionLhs,
			T.ParsedByKindId
		>;
	}
	return drillIn<T.NamedExpressionLhs>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _NodeData).$span
		}),
		tree
	);
}

