export function wrapRightHandSide(
	data: T.RightHandSide & { readonly $other?: T.RightHandSide | readonly T.RightHandSide[] },
	tree: TreeHandle
): SupertypeSurface<T.RightHandSide, T.ParsedByKindId> {
	if (typeof data === 'number') return data as unknown as SupertypeSurface<T.RightHandSide, T.ParsedByKindId>;
	const node = _keepModelledSlots(data, [
		'_expression',
		'_expression_list',
		'_assignment',
		'_augmented_assignment',
		'_pattern_list',
		'_yield',
		'_comparison_operator',
		'_not_operator',
		'_boolean_operator',
		'_lambda',
		'_print_keyword',
		'_await',
		'_binary_operator',
		'_exec_keyword',
		'_async_keyword',
		'_await_keyword',
		'_type_keyword',
		'_match_keyword',
		'_string',
		'_concatenated_string',
		'_integer_hex',
		'_integer_octal',
		'_integer_binary',
		'_integer_decimal_long',
		'_integer_decimal_imaginary',
		'_integer_decimal_plain',
		'_float_point',
		'_float_leading_point',
		'_float_scientific',
		'_true',
		'_false',
		'_none',
		'_unary_operator',
		'_attribute',
		'_subscript',
		'_call',
		'_list',
		'_list_comprehension',
		'_dictionary',
		'_dictionary_comprehension',
		'_set',
		'_set_comprehension',
		'_tuple',
		'_parenthesized_expression',
		'_generator_expression',
		'_ellipsis',
		'_list_splat_pattern',
		'_conditional_expression',
		'_named_expression',
		'_as_pattern',
		'_assignment_eq',
		'_assignment_type',
		'_assignment_typed'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'expression',
		'expression_list',
		'assignment',
		'augmented_assignment',
		'pattern_list',
		'yield',
		'comparison_operator',
		'not_operator',
		'boolean_operator',
		'lambda',
		'print_keyword',
		'await',
		'binary_operator',
		'exec_keyword',
		'async_keyword',
		'await_keyword',
		'type_keyword',
		'match_keyword',
		'string',
		'concatenated_string',
		'integer_hex',
		'integer_octal',
		'integer_binary',
		'integer_decimal_long',
		'integer_decimal_imaginary',
		'integer_decimal_plain',
		'float_point',
		'float_leading_point',
		'float_scientific',
		'true',
		'false',
		'none',
		'unary_operator',
		'attribute',
		'subscript',
		'call',
		'list',
		'list_comprehension',
		'dictionary',
		'dictionary_comprehension',
		'set',
		'set_comprehension',
		'tuple',
		'parenthesized_expression',
		'generator_expression',
		'ellipsis',
		'list_splat_pattern',
		'conditional_expression',
		'named_expression',
		'as_pattern',
		'assignment_eq',
		'assignment_type',
		'assignment_typed'
	]) as T.RightHandSide | readonly T.RightHandSide[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'expression',
			'expression_list',
			'assignment',
			'augmented_assignment',
			'pattern_list',
			'yield',
			'comparison_operator',
			'not_operator',
			'boolean_operator',
			'lambda',
			'print_keyword',
			'await',
			'binary_operator',
			'exec_keyword',
			'async_keyword',
			'await_keyword',
			'type_keyword',
			'match_keyword',
			'string',
			'concatenated_string',
			'integer_hex',
			'integer_octal',
			'integer_binary',
			'integer_decimal_long',
			'integer_decimal_imaginary',
			'integer_decimal_plain',
			'float_point',
			'float_leading_point',
			'float_scientific',
			'true',
			'false',
			'none',
			'unary_operator',
			'attribute',
			'subscript',
			'call',
			'list',
			'list_comprehension',
			'dictionary',
			'dictionary_comprehension',
			'set',
			'set_comprehension',
			'tuple',
			'parenthesized_expression',
			'generator_expression',
			'ellipsis',
			'list_splat_pattern',
			'conditional_expression',
			'named_expression',
			'as_pattern',
			'assignment_eq',
			'assignment_type',
			'assignment_typed'
		]);
	if (filtered === undefined && (typeof (node as _NodeData).$text === 'string' || treeHandleOf(node) !== undefined)) {
		return drillInSelf<T.RightHandSide>(node as T.RightHandSide, tree) as unknown as SupertypeSurface<
			T.RightHandSide,
			T.ParsedByKindId
		>;
	}
	return drillIn<T.RightHandSide>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _NodeData).$span
		}),
		tree
	);
}

